-- L1 buffer, index, identity of every row
local buf = P(G + 0x2E49C28)
out('FPT_L1 buffer', h(buf), '(non-null once settings are loaded)')
local idx, bad, n = G + 0x3182E70, 0, 0
for i = 0, 355 do
  local row = P(idx + i * 8)
  if row then n = n + 1; if U32(row) ~= i then bad = bad + 1 end end
end
out('FPT_L1 rows', n, 'identity mismatches', bad, '(expect 355 rows, slot 0 empty, 0 mismatches)',
    '| slot 356 (past the table):', h(P(idx + 356 * 8)))
-- L2 template field +0xF8 and the new field +0xF4 over all rows
local hist, f4 = {}, {}
for i = 1, 355 do
  local row = P(idx + i * 8)
  if row then
    local t = U32(row + 0xF8) or -1; hist[t] = (hist[t] or 0) + 1
    local v = U32(row + 0xF4) or -1; if v <= 3 then f4[v] = (f4[v] or 0) + 1 end
  end
end
local parts = {}
for k, v in pairs(hist) do parts[#parts + 1] = k .. ':' .. v end
table.sort(parts)
out('FPT_L2 +0xF8 template histogram', table.concat(parts, ' '), '(expect only 0,1,2,3 with the mod off: 0 most rows,',
    '3 = plasma/lasers; with the mod on, the 95 targets move 0 -> 3)')
local p4 = {}
for k, v in pairs(f4) do p4[#p4 + 1] = k .. ':' .. v end
out('FPT_L2 +0xF4 rows holding 0..3', table.concat(p4, ' '), '(expect few or none: +0xF4 is no longer the template)')
