  local row = P(idx + t[1] * 8)
  local okrow = row and U32(row) == t[1] and U32(row + 8) == t[2] and U32(row + 0x90) == t[3]
  local tmpl = row and U32(row + 0xF8)
  local r = row and F32(row + 0xA4)
  if okrow then good = good + 1 else wrong = wrong + 1; out('FPT_L3 MISMATCH', t[1], t[5], h(row and U32(row + 8)), row and U32(row + 0x90)) end
  if tmpl == 0 then at0 = at0 + 1 elseif tmpl == 3 then at3 = at3 + 1 end
  if r and r > 0 then radius = radius + 1; out('FPT_L3 +0xA4 > 0 (new extra sweep applies)', t[1], t[5], fmt('%.3f', r)) end
  if t[4] == 0 then out('FPT_L3 excluded (medium) row', t[1], t[5], 'ok', tostring(okrow), 'template', tmpl) end
end
out('FPT_L3 targets', #T, 'match', good, 'mismatch', wrong, 'template 0', at0, 'template 3', at3, 'with +0xA4 > 0', radius,
