local okk, st = pcall(function() return rawget(_G, 'FoliagePassThrough') end)
if okk and type(st) == 'table' then out('FPT_L4 status', st.status, 'applied', tostring(st.applied))
else out('FPT_L4 FoliagePassThrough table not visible here; read FoliagePassThrough.log') end
